function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 300000) return 's needs 1 to 3 * 10^5 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > s.length) return 'k is between 1 and the length of s.';
  return null;
}

