function numberOfSubstrings(s, k) {
  const count = new Array(26).fill(0);
  let left = 0;
  let total = 0;
  for (let right = 0; right < s.length; right++) {
    const c = s.charCodeAt(right) - 97;
    count[c]++;
    while (count[c] >= k) {
      count[s.charCodeAt(left) - 97]--;
      left++;
    }
    total += left;
  }
  return total;
}

