function numberOfSubstrings(s, k) {
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    const freq = new Map();
    let found = false;
    for (let j = i; j < s.length; j++) {
      freq.set(s[j], (freq.get(s[j]) || 0) + 1);
      if (freq.get(s[j]) >= k) found = true;
      if (found) total++;
    }
  }
  return total;
}

