function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const letters = 1 + Math.floor(rand() * (size === 'large' ? 26 : 4));
  // Mostly small k so that many substrings qualify; sometimes one near the letters' average
  // frequency so that few or none do.
  const k = rand() < 0.7
    ? 1 + Math.floor(rand() * Math.min(n, size === 'large' ? 20 : 4))
    : 1 + Math.floor(rand() * Math.min(n, Math.ceil(2 * n / letters)));
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
  return [s, k];
}
